                    "sql": "create or replace table redtape_db.maplemonk.redtape_db_operations_factitems as SELECT marketplace, channel, portal, brand, order_id, reference_code, payment_mode, courier, awb as awb_number, shipping_status, order_status, final_shipping_status, easyecom_status, order_timestamp, confirm_date, order_date, dispatch_date Manifest_date, shipping_last_update_date, delivered_date, delivered_status, days_in_shipment, warehouse_name, city, state, pincode, sku, sku_code, article, product_id, product_name, product_name_final, product_category, category_mapped, gender, division, size, colour, quantity, mrp, discount_percent, selling_price, shipping_price, return_flag, returned_quantity, returned_sales, cancelled_quantity, CASE WHEN lower(final_shipping_status) IN (\'rto in-transit\',\'rto out for delivery\',\'rto initiated\', \'rto undelivered\', \'delivered to origin\') THEN \'RTO\' WHEN lower(final_shipping_status) IN (\'in transit\',\'handover\',\'picked up\',\'out for pickup\',\'pickup scheduled\', \'pickup rescheduled\',\'pickup exception\',\'shipment created\') THEN \'IN_TRANSIT\' WHEN lower(final_shipping_status) IN (\'out for delivery\' ) THEN \'OUT_FOR_DELIVERY\' WHEN lower(final_shipping_status) IN (\'delivered\') THEN \'DELIVERED\' WHEN lower(final_shipping_status) IN (\'returned\',\'reverse pickup scheduled\') THEN \'RETURNED\' WHEN lower(final_shipping_status) IN (\'cancelled\') THEN \'CANCELLED\' WHEN lower(final_shipping_status) IN (\'undelivered\') THEN \'UNDELIVERED\' WHEN lower(final_shipping_status) IN (\'shipment lost\') THEN \'LOST\' WHEN lower(final_shipping_status) IN (\'shipment onhold\',\'shipment error\') THEN \'ON_HOLD\' END AS final_status, case when EXTRACT(HOUR FROM CONFIRM_DATE) <14 then CONFIRM_DATE::DATE when EXTRACT(HOUR FROM CONFIRM_DATE) >14 then DATEADD(DAY, 1,CONFIRM_DATE::DATE) else DISPATCH_TAT::DATE end AS Target_dispatch_Pre ,case when upper(dayname(Target_dispatch_Pre)) = \'SUN\' then DATEADD(DAY, 1, Target_dispatch_Pre) else Target_dispatch_Pre END as Target_dispatch_date ,upper(case when lower(final_status) like \'%cancel%\' then \'CANCELLED\' when not(lower(final_status) like \'%cancel%\') and Manifest_date::Date is null then \'ORDER YET TO BE CONFIRMED\' when not(lower(final_status) like \'%cancel%\') and Manifest_date::date is NULL then \'NOT DISPATCHED\' when Manifest_date::date is not NULL then \'DISPATCHED\' when Manifest_date::date is NULL then \'NOT DISPATCHED\' end) as dispatch_status ,upper(case when lower(final_status) like \'%cancel%\' then \'CANCELLED\' when not(lower(final_status) like \'%cancel%\') and Delivered_Date::date is NULL then \'NOT DELIVERED\' else \'DELIVERED\' end) as delivery_status ,case when lower(final_status) like \'%cancel%\' then \'CANCELLED\' when not(lower(final_status) like \'%cancel%\') and Target_dispatch_date is null then \'ORDER YET TO BE CONFIRMED\' when not(lower(final_status) like \'%cancel%\') and Manifest_date is NULL and convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::date > Target_dispatch_date::Date then \'NOT DISPATCHED - DELAYED\' when not(lower(final_status) like \'%cancel%\') and Manifest_date is NULL and convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::date <= Target_dispatch_date::Date then \'NOT DISPATCHED - WITHIN SLA\' when not(lower(final_status) like \'%cancel%\') and Manifest_date::date <= Target_dispatch_date::Date then \'DISPATCHED - ON TIME\' when not(lower(final_status) like \'%cancel%\') and Manifest_date::date > Target_dispatch_date::Date then \'DISPATCHED - DELAYED\' else \'OTHERS\' end DISPATCH_SLA_STATUS ,case when upper(final_status) in (\'DELIVERED\') then 1 else 0 end as delivered_order ,case when upper(final_status) = \'OUT_FOR_DELIVERY\' then 1 else 0 end as out_for_delivery_Order ,case when upper(final_status) = \'UNDELIVERED\' then 1 else 0 end as undelivered_Order ,case when upper(final_status) = \'ON_HOLD\' then 1 else 0 end as on_hold_order ,case when upper(final_status) = \'IN_TRANSIT\' then 1 else 0 end as In_Transit_order ,case when upper(final_status) = \'RTO\' then 1 else 0 end as RTO_Order ,case when upper(final_status) = \'RETURNED\' then 1 else 0 end as Returned_order ,case when upper(final_status) = \'LOST\' then 1 else 0 end as Lost_Order ,case when upper(final_status) = \'CANCELLED\' then 1 else 0 end as cancelled_order ,CASE WHEN delivered_order = 1 THEN DATEDIFF(HOUR,order_timestamp::timestamp, DELIVERED_DATE::timestamp) ELSE DATEDIFF( HOUR,order_timestamp::timestamp,CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', CURRENT_TIMESTAMP())::timestamp) END AS Time_From_Order ,case when delivered_order = 1 then datediff(\'day\',order_date::timestamp ,delivered_date::timestamp ) else datediff(\'day\',order_date::timestamp ,convert_timezone(\'UTC\', \'Asia/Kolkata\', current_timestamp())::timestamp) end as Days_From_Order ,datediff(\'hour\',order_timestamp::timestamp ,delivered_date::timestamp) o2d_delivery_Speed ,datediff(\'day\',order_timestamp::timestamp ,delivered_date::timestamp) o2d_delivery_Speed_Days ,datediff(\'hour\',Manifest_date::timestamp ,delivered_date::timestamp) s2d_delivery_Speed ,datediff(\'day\',Manifest_date::timestamp ,delivered_date::timestamp) s2d_delivery_Speed_Days ,datediff(\'hour\',order_timestamp::timestamp ,Manifest_date::timestamp) Dispatch_Speed ,datediff(\'day\',order_timestamp::timestamp ,Manifest_date::timestamp) Dispatch_Speed_Days ,case when delivered_order = 1 then datediff(\'hour\',Manifest_date::timestamp , delivered_date::timestamp ) end as Delivery_Speed ,case when delivered_order = 1 then datediff(\'hour\',Manifest_date::timestamp ,delivered_date::timestamp ) else datediff(\'hour\',Manifest_date::timestamp ,convert_timezone(\'UTC\', \'Asia/Kolkata\', current_timestamp())::timestamp) end as delivery_time ,greatest(datediff(\'day\',order_timestamp::timestamp ,coalesce(Manifest_date::timestamp,convert_timezone(\'UTC\', \'Asia/Kolkata\', current