_Speed_Days <=3 then \'3 days\' when Dispatch_Speed_Days <= 5 then \'4 - 5 days\' when Manifest_date is not NULL then \'> 5 days\' when Manifest_date is NULL then \'Not Dispatched\' end as Dispatch_Speed_Days_flag ,Case when Dispatch_Flag=0 then \'Same Day\' when Dispatch_Flag=1 then \'Next Day\' else \'2+ Days\' end as Final_Dispatch_Bucket ,CASE WHEN Delivery_Speed <= 24 THEN \'<=24 hours\' WHEN Delivery_Speed <= 48 THEN \'25 - 48 hours\' WHEN Delivery_Speed <= 72 THEN \'49 - 72 hours\' WHEN Delivery_Speed <= 96 THEN \'73 - 96 hours\' WHEN Delivery_Speed <= 120 THEN \'97 - 120 hours\' WHEN Delivery_Speed > 120 THEN \'> 120 hours\' ELSE \'NOT DELIVERED\' END AS delivery_time_flag ,CASE WHEN delivery_time <= 1 THEN \'Within a day\' WHEN delivery_time <= 2 THEN \'2 days\' WHEN delivery_time <= 5 THEN \'5 days\' WHEN delivery_time <= 7 THEN \'7 days\' WHEN delivery_time > 9 THEN \'>9 days\' ELSE \'NOT DELIVERED\' END AS delivery_time_days_flag FROM redtape_db.maplemonk.redtape_db_sales_consolidated;",
